const input = {"status_kind":"success","result_type":"state_update_result","execution_context_id":"33333333-3333-3333-3333-333333333333","thread_id":"55555555-5555-5555-5555-555555555555","tenant_id":"44444444-4444-4444-4444-444444444444","allowed_next_stage":"WF-RC-01","response_generation_allowed":true,"channel":"telegram","locale":"ro","state_update_result":{"status":"success","summary":"Am procesat cererea ta.","applied_write_classes":["execution_state_update"],"blocked_write_classes":["domain_event_write"],"warnings":[{"code":"CAL_UNREACHABLE","message":"Sincronizarea calendar a eșuat temporar."},"atenție: timpul estimat poate varia"],"followup_requests":[{"code":"NEED_DATE","message":"Care e data limită exactă?"},{"code":"NEED_RECIPIENT","message":"Cui trebuie trimis?"}],"actions_acknowledged":["draft_message"],"user_visible_facts":["conversația a fost salvată"]}};
const required = ['status_kind','result_type','execution_context_id','thread_id','tenant_id','state_update_result','allowed_next_stage','response_generation_allowed'];
const missing = required.filter(k => !(k in input));
if (missing.length) {
  return [{ json: {
    status_kind: 'error',
    result_type: 'composition_error',
    error: {
      code: 'INVALID_RESPONSE_COMPOSITION_INPUT',
      message: 'Missing required top-level field(s) for response composition.',
      missing_fields: missing,
      details: { received_keys: Object.keys(input).sort() }
    },
    _valid: false
  }}];
}
if (input.status_kind !== 'success' || input.result_type !== 'state_update_result') {
  return [{ json: {
    status_kind: 'error',
    result_type: 'composition_error',
    error: {
      code: 'INVALID_RESPONSE_COMPOSITION_INPUT',
      message: 'Unsupported envelope for RC.',
      missing_fields: [],
      details: { status_kind: input.status_kind, result_type: input.result_type }
    },
    _valid: false
  }}];
}
if (input.allowed_next_stage !== 'WF-RC-01' || input.response_generation_allowed !== true) {
  return [{ json: {
    status_kind: 'error',
    result_type: 'composition_error',
    error: {
      code: 'COMPOSITION_NOT_ALLOWED',
      message: 'RC is not allowed to compose for this envelope.',
      missing_fields: [],
      details: { allowed_next_stage: input.allowed_next_stage, response_generation_allowed: input.response_generation_allowed }
    },
    _valid: false
  }}];
}
const sur = input.state_update_result || {};
if (!sur.status || !sur.summary) {
  return [{ json: {
    status_kind: 'error',
    result_type: 'composition_error',
    error: {
      code: 'INVALID_RESPONSE_COMPOSITION_INPUT',
      message: 'state_update_result is incomplete.',
      missing_fields: [],
      details: { state_update_result: sur }
    },
    _valid: false
  }}];
}
return [{ json: {
  ...input,
  channel: input.channel || 'telegram',
  locale: input.locale || 'ro',
  _valid: true
}}];
